 Fighter:[[1,'Weapon Mastery','Use mastery properties for your chosen weapon types. Your class level determines how many you know.'],[5,'Extra Attack','Attack twice, rather than once, when taking the Attack action on your turn.'],[9,'Tactical Master','Replace an eligible mastery property with Push, Sap, or Slow when attacking.'],[11,'Two Extra Attacks','Make three attacks with your Attack action on your turn.'],[13,'Studied Attacks','After missing a creature, gain Advantage on your next attack against it before your next turn ends.'],[20,'Three Extra Attacks','Make four attacks with your Attack action on your turn.']],
 Paladin:[[1,'Spellcasting','Prepare and cast Paladin spells using Charisma. Spell slots and preparation have separate limits.'],[1,'Weapon Mastery','Use mastery properties for your chosen weapon types.'],[5,'Extra Attack','Attack twice with your Attack action on your turn. Extra Attack from another class does not stack.'],[6,'Aura of Protection','While not Incapacitated, grant your Charisma-based saving throw bonus to yourself and nearby allies. Enter this bonus manually in adjustments.'],[10,'Aura of Courage','Your aura protects you and allies in it from Frightened under the feature’s conditions.'],[11,'Radiant Strikes','Your eligible melee weapon and Unarmed Strike hits deal an extra 1d8 Radiant damage.'],[18,'Aura Expansion','Your Paladin aura grows to a 30-foot radius.']],
 Barbarian:[[1,'Unarmored Defense','Without armor, base AC is 10 + Dexterity + Constitution modifiers; a Shield is permitted.'],[1,'Weapon Mastery','Use mastery properties for chosen eligible weapons.'],[2,'Danger Sense','Advantage on Dexterity saves unless Incapacitated.'],[3,'Primal Knowledge','Gain an additional class skill; while raging, certain checks can use Strength.'],[5,'Extra Attack','Make two attacks with your Attack action.'],[5,'Fast Movement','Your Speed increases by 10 feet while not wearing Heavy armor.'],[7,'Feral Instinct','Gain Advantage on Initiative rolls.'],[18,'Indomitable Might','Certain low Strength checks and saves can use your Strength score instead.'],[20,'Primal Champion','Increase Strength and Constitution, including their maximums, as the feature describes.']],
 Bard:[[1,'Spellcasting','Prepare and cast Bard spells using Charisma.'],[2,'Expertise','Double proficiency bonus for your chosen proficient skills. Choose them on the sheet.'],[2,'Jack of All Trades','Add half proficiency bonus to eligible ability checks lacking proficiency; sheet skill bonuses include it.'],[10,'Magical Secrets','Expand the spell lists you can choose from when preparing spells.']],
 Cleric:[[1,'Spellcasting','Prepare and cast Cleric spells using Wisdom.'],[5,'Sear Undead','Turn Undead can also deal Radiant damage under this feature.'],[7,'Blessed Strikes','Choose the weapon-damage or cantrip-damage benefit on your sheet.'],[14,'Improved Blessed Strikes','Your chosen Blessed Strikes benefit improves.']],
 Druid:[[1,'Spellcasting','Prepare and cast Druid spells using Wisdom.'],[1,'Druidic','Know Druidic and gain the feature’s nature-communication benefits.'],[7,'Elemental Fury','Choose the weapon/Wild Shape damage or cantrip damage benefit.'],[15,'Improved Elemental Fury','Your selected Elemental Fury option improves.'],[18,'Beast Spells','Cast many spells while using Wild Shape, subject to component restrictions.']],
 Monk:[[1,'Martial Arts','Improve Unarmed Strikes and Monk weapons while meeting the armor and weapon requirements.'],[1,'Unarmored Defense','Without armor or Shield, base AC is 10 + Dexterity + Wisdom modifiers.'],[2,'Unarmored Movement','Gain a level-based Speed bonus without armor or Shield.'],[4,'Slow Fall','Use a Reaction to reduce falling damage.'],[5,'Extra Attack','Make two attacks with your Attack action.'],[6,'Empowered Strikes','Choose Force damage for eligible Unarmed Strikes.'],[7,'Evasion','Certain Dexterity-save effects deal reduced or no damage.'],[9,'Acrobatic Movement','Move on vertical surfaces and across liquids during your turn while eligible.'],[10,'Heightened Focus','Your Focus-powered combat options improve.'],[15,'Perfect Focus','Restore Focus to the feature’s minimum when rolling Initiative.']],
 Ranger:[[1,'Spellcasting','Prepare and cast Ranger spells using Wisdom.'],[1,'Weapon Mastery','Use mastery properties for chosen weapon types.'],[2,'Deft Explorer','Gain Expertise in a proficient skill and additional languages.'],[5,'Extra Attack','Make two attacks with your Attack action.'],[6,'Roving','Gain movement benefits when not wearing Heavy armor.'],[9,'Expertise','Gain Expertise in additional proficient skills.'],[13,'Relentless Hunter','Taking damage no longer breaks Concentration on Hunter’s Mark.'],[17,'Precise Hunter','Gain Advantage against the target of your Hunter’s Mark.'],[18,'Feral Senses','Gain Blindsight out to 30 feet.'],[20,'Foe Slayer','Hunter’s Mark uses d10 damage dice.']],
 Rogue:[[1,'Expertise','Double proficiency bonus for selected proficient skills.'],[1,'Sneak Attack','Once per turn, add level-based damage to an eligible Finesse or ranged weapon hit when the feature’s conditions are met.'],[1,'Thieves’ Cant','Know Thieves’ Cant and an additional language.'],[1,'Weapon Mastery','Use mastery properties for chosen weapon types.'],[2,'Cunning Action','Use a Bonus Action to Dash, Disengage, or Hide.'],[5,'Cunning Strike','Trade Sneak Attack dice for eligible extra effects.'],[5,'Uncanny Dodge','Use a Reaction to halve damage from a visible attacker’s hit.'],[7,'Evasion','Certain Dexterity-save effects deal reduced or no damage.'],[7,'Reliable Talent','Treat low d20 rolls on proficient skill or tool checks as 10.'],[11,'Improved Cunning Strike','Apply two eligible Cunning Strike effects to a Sneak Attack.'],[14,'Devious Strikes','Gain further Cunning Strike options.'],[15,'Slippery Mind','Gain Wisdom and Charisma saving throw proficiency.'],[18,'Elusive','Attack rolls cannot have Advantage against you unless you are Incapacitated.']],
 Sorcerer:[[1,'Spellcasting','Prepare and cast Sorcerer spells using Charisma.'],[2,'Font of Magic','Convert between Sorcery Points and eligible spell slots under the feature’s limits.'],[7,'Sorcery Incarnate','Your Innate Sorcery and Metamagic options improve.']],
 Warlock:[[1,'Pact Magic','Cast Warlock spells using Charisma with Pact Magic slots, recovered on a Short or Long Rest.'],[1,'Eldritch Invocations','Choose invocations you qualify for; record the choices in class notes.'],[9,'Contact Patron','Gain the feature’s Contact Other Plane option.']],
 Wizard:[[1,'Spellcasting','Prepare and cast Wizard spells using Intelligence; keep a spellbook.'],[1,'Ritual Adept','Cast eligible rituals from your spellbook without preparing them.'],[2,'Scholar','Gain Expertise in a chosen eligible proficient knowledge skill.'],[5,'Memorize Spell','Use the feature’s Short Rest option to replace one prepared Wizard spell.'],[18,'Spell Mastery','Choose eligible low-level spells for the feature’s slot-free casting.']]
